using System.Threading;
using System.Threading.Tasks;

class Program
{
    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);

        const int minDepth = 4;
        int maxDepth = Math.Max(minDepth + 2, n);
        int stretchDepth = maxDepth + 1;

        int stretchCheck = TreeNode.Create(stretchDepth).Check();
        Console.WriteLine($"stretch tree of depth {stretchDepth}\t check: {stretchCheck}");

        TreeNode longLivedTree = TreeNode.Create(maxDepth);

        for (int depth = minDepth; depth <= maxDepth; depth += 2)
        {
            int iterations = 1 << (maxDepth - depth + minDepth);
            int check = 0;

            int numThreads = Math.Min(Environment.ProcessorCount, iterations);
            Parallel.For(0, numThreads, threadId =>
            {
                int from = (int)((long)iterations * threadId / numThreads);
                int to = (int)((long)iterations * (threadId + 1) / numThreads);
                int localCheck = 0;

                for (int i = from; i < to; i++)
                {
                    localCheck += TreeNode.Create(depth).Check();
                }

                Interlocked.Add(ref check, localCheck);
            });

            Console.WriteLine($"{iterations}\t trees of depth {depth}\t check: {check}");
        }

        Console.WriteLine($"long lived tree of depth {maxDepth}\t check: {longLivedTree.Check()}");
    }

    private sealed class TreeNode
    {
        private readonly TreeNode? left;
        private readonly TreeNode? right;

        public TreeNode()
        {
        }

        public TreeNode(TreeNode left, TreeNode right)
        {
            this.left = left;
            this.right = right;
        }

        public static TreeNode Create(int depth)
        {
            return depth == 0
                ? new TreeNode()
                : new TreeNode(Create(depth - 1), Create(depth - 1));
        }

        public int Check()
        {
            return left == null ? 1 : 1 + left.Check() + right!.Check();
        }
    }
}
