{
    private const int IM = 139968;
    private const int IA = 3877;
    private const int IC = 29573;

    private const int LineLength = 60;
    private const int LineWithNl = 61;
    private const int LinesPerBuffer = 4096;
    private const int BufferSize = LinesPerBuffer * LineWithNl;

    private const string AluString =
        "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGG" +
        "GAGGCCGAGGCGGGCGGATCACCTGAGGTCAGGAGTTCGAGA" +
        "CCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACTAAAAAT" +
