        "AGGCGGAGGTTGCAGTGAGCCGAGATCGCGCCACTGCACTCC" +
        "AGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

    private struct Frequency
    {
        public readonly byte Character;
        public double Probability;

        public Frequency(char character, double probability)
        {
            Character = (byte)character;
            Probability = probability;
        }
    }

    private static byte[] BuildLookup(Frequency[] frequencies)
    {
        var lookup = new byte[IM];
        double cumulative = 0.0;
        for (int i = 0; i < frequencies.Length; i++)
        {
            cumulative += frequencies[i].Probability;
            frequencies[i].Probability = cumulative;
        }
        frequencies[^1].Probability = 1.0;

        for (int seed = 0; seed < IM; seed++)
        {
            double p = (double)seed / IM;
            for (int i = 0; i < frequencies.Length; i++)
            {
                if (frequencies[i].Probability >= p)
                {
                    lookup[seed] = frequencies[i].Character;
                    break;
                }
            }
        }

        return lookup;
    }

    private static void WriteAlu(Stream stream, byte[] buffer, byte[] alu, int count)
    {
