                for (int l = 0; l < lines; l++)
                {
                    Buffer.BlockCopy(alu, aluPos, buffer, bufIdx, LineLength);
                    bufIdx += LineLength;
                    buffer[bufIdx++] = (byte)'\n';
                    aluPos += LineLength;
