using System;
using System.Threading;

class Program
{
    static int n;
    static int totalPerms;
    const int ChunkSize = 16384;
    static int numChunks;
    static int currentChunk;
    static int globalMaxFlips;
    static int globalChecksum;
    static int[] fact = null!;

    static void FirstPermutation(Span<int> p, Span<int> pp, Span<int> count, int idx, int n, int[] fact)
    {
        for (int i = 0; i < n; ++i) p[i] = i;
        for (int i = n - 1; i > 0; --i)
        {
            int d = idx / fact[i];
            count[i] = d;
            idx %= fact[i];
            for (int j = 0; j <= i; ++j) pp[j] = p[j];
            for (int j = 0; j <= i; ++j)
            {
                p[j] = (j + d <= i) ? pp[j + d] : pp[j + d - i - 1];
            }
        }
    }

    static void Worker()
    {
        Span<int> p = stackalloc int[16];
        Span<int> pp = stackalloc int[16];
        Span<int> count = stackalloc int[16];
        Span<int> q = stackalloc int[16];

        int localMaxFlips = 0;
        int localChecksum = 0;

        while (true)
        {
            int chunkIdx = Interlocked.Increment(ref currentChunk) - 1;
            if (chunkIdx >= numChunks) break;

            int start = chunkIdx * ChunkSize;
            int end = Math.Min(start + ChunkSize, totalPerms);

            FirstPermutation(p, pp, count, start, n, fact);

            for (int k = start; k < end; k++)
            {
                int first = p[0];
                int flips = 0;
                if (first > 0)
                {
                    for (int c = 0; c < n; c++) q[c] = p[c];
                    flips = 1;
                    while (true)
                    {
                        int t2 = q[first];
                        if (t2 == 0) break;
                        q[first] = first;
                        if (first > 2)
                        {
                            int lo = 1, hi = first - 1;
                            while (lo < hi)
                            {
                                int tmp = q[lo];
                                q[lo] = q[hi];
                                q[hi] = tmp;
                                lo++;
                                hi--;
                            }
                        }
                        first = t2;
                        flips++;
                    }
                }

                if (flips > localMaxFlips) localMaxFlips = flips;
                localChecksum += ((k & 1) == 0) ? flips : -flips;

                if (k < end - 1)
                {
                    int pfirst = p[1];
                    p[1] = p[0];
                    p[0] = pfirst;

                    int i = 1;
                    while (++count[i] > i)
                    {
                        count[i] = 0;
                        i++;
                        int next = p[0];
                        for (int j = 0; j < i; j++)
                        {
                            p[j] = p[j + 1];
                        }
                        p[i] = next;
                    }
                }
            }
        }

        Interlocked.Add(ref globalChecksum, localChecksum);

        int curMax;
        do
        {
            curMax = globalMaxFlips;
            if (localMaxFlips <= curMax) break;
        } while (Interlocked.CompareExchange(ref globalMaxFlips, localMaxFlips, curMax) != curMax);
    }

    static void Main(string[] args)
    {
        n = args.Length > 0 ? int.Parse(args[0]) : 11;

        fact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++)
        {
            fact[i] = fact[i - 1] * i;
        }

        totalPerms = fact[n];
        numChunks = (totalPerms + ChunkSize - 1) / ChunkSize;
        currentChunk = 0;

        int threadCount = Math.Min(Environment.ProcessorCount, numChunks);
        if (threadCount <= 1)
        {
            Worker();
        }
        else
        {
            Thread[] threads = new Thread[threadCount];
            for (int t = 0; t < threadCount; t++)
            {
                threads[t] = new Thread(Worker);
                threads[t].Start();
            }
            for (int t = 0; t < threadCount; t++)
            {
                threads[t].Join();
            }
        }

        Console.WriteLine(globalChecksum);
        Console.WriteLine($"Pfannkuchen({n}) = {globalMaxFlips}");
    }
}
