using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Threading.Tasks;

class Program
{
    private static readonly byte[] ToCode = new byte[256];
    private static readonly string[] FragmentStrings =
    {
        "GGT",
        "GGTA",
        "GGTATT",
        "GGTATTTTAATT",
        "GGTATTTTAATTTATAGT"
    };

    private static int bufLen;
    private static int bufPos;
    private static readonly byte[] ReadBuf = new byte[65536];

    private static byte NextByte(Stream stream)
    {
        if (bufPos >= bufLen)
        {
            bufPos = 0;
            bufLen = stream.Read(ReadBuf, 0, ReadBuf.Length);
            if (bufLen <= 0) return 0;
        }
        return ReadBuf[bufPos++];
    }

    private static ulong Encode(string s)
    {
        ulong key = 0;
        foreach (char c in s)
        {
            key = (key << 2) | ToCode[(byte)c];
        }
        return key;
    }

    private static string Decode(ulong key, int len)
    {
        char[] chars = new char[len];
        for (int i = len - 1; i >= 0; i--)
        {
            chars[i] = "ACGT"[(int)(key & 3)];
            key >>= 2;
        }
        return new string(chars);
    }

    private sealed class Worker
    {
        public readonly long[] C1 = new long[4];
        public readonly long[] C2 = new long[16];
        public readonly long[] FragmentCounts = new long[5];
    }

    static void Main(string[] args)
    {
        int n = args.Length > 0 ? int.Parse(args[0]) : 0;
        _ = n;

        Array.Fill(ToCode, (byte)255);
        ToCode['A'] = ToCode['a'] = 0;
        ToCode['C'] = ToCode['c'] = 1;
        ToCode['G'] = ToCode['g'] = 2;
        ToCode['T'] = ToCode['t'] = 3;

        using var stdin = Console.OpenStandardInput();

        // Find ">THREE"
        byte b;
        while ((b = NextByte(stdin)) != 0)
        {
            if (b == '>')
            {
                if (NextByte(stdin) == 'T' &&
                    NextByte(stdin) == 'H' &&
                    NextByte(stdin) == 'R' &&
                    NextByte(stdin) == 'E' &&
                    NextByte(stdin) == 'E')
                {
                    while ((b = NextByte(stdin)) != 0 && b != '\n') { }
                    break;
                }
            }
        }

        // Read sequence data
        byte[] seq = new byte[1024 * 1024];
        int seqLen = 0;

        while ((b = NextByte(stdin)) != 0)
        {
            if (b == '>') break;
            byte code = ToCode[b];
            if (code != 255)
            {
                if (seqLen == seq.Length)
                {
                    Array.Resize(ref seq, seq.Length * 2);
                }
                seq[seqLen++] = code;
            }
        }

        ulong[] targetKeys = new ulong[5];
        ulong[] masks = new ulong[5];
        for (int f = 0; f < 5; f++)
        {
            targetKeys[f] = Encode(FragmentStrings[f]);
            masks[f] = (1UL << (2 * FragmentStrings[f].Length)) - 1;
        }

        int numThreads = Environment.ProcessorCount;
        if (seqLen < 20000 || numThreads <= 1)
        {
            numThreads = 1;
        }

        Worker[] workers = new Worker[numThreads];
        for (int i = 0; i < numThreads; i++) workers[i] = new Worker();

        int chunkSize = (seqLen + numThreads - 1) / numThreads;

        Parallel.For(0, numThreads, t =>
        {
            int start = t * chunkSize;
            int end = Math.Min(start + chunkSize, seqLen);
            if (start >= end) return;

            Worker w = workers[t];

            ulong rollingKey = 0;
            int primeStart = Math.Max(0, start - 17);
