                if (i >= 3 && (rollingKey & masks[1]) == targetKeys[1]) w.FragmentCounts[1]++;
                if (i >= 5 && (rollingKey & masks[2]) == targetKeys[2]) w.FragmentCounts[2]++;
                if (i >= 11 && (rollingKey & masks[3]) == targetKeys[3]) w.FragmentCounts[3]++;
