                c2[rollingKey & 15]++;
                if ((rollingKey & m0) == t0) fc0++;
                if ((rollingKey & m1) == t1) fc1++;
                if ((rollingKey & m2) == t2) fc2++;
                if ((rollingKey & m3) == t3) fc3++;
                if ((rollingKey & m4) == t4) fc4++;
