            w.FragmentCounts[0] += fc0;
            w.FragmentCounts[1] += fc1;
            w.FragmentCounts[2] += fc2;
            w.FragmentCounts[3] += fc3;
            w.FragmentCounts[4] += fc4;
        });

        long[] totalC1 = new long[4];
        long[] totalC2 = new long[16];
        long[] totalFragments = new long[5];

