        {
            if (totalC2[i] > 0)
                list2.Add((Decode((ulong)i, 2), totalC2[i]));
        }
        list2.Sort((a, b) =>
        {
            int cmp = b.Count.CompareTo(a.Count);
            if (cmp != 0) return cmp;
            return string.CompareOrdinal(a.Key, b.Key);
        });

        double sum2 = 0;
        foreach (var item in list2) sum2 += item.Count;
        foreach (var item in list2)
        {
            double pct = sum2 > 0 ? (item.Count * 100.0 / sum2) : 0.0;
            Console.WriteLine(string.Format(CultureInfo.InvariantCulture, "{0} {1:F3}", item.Key, pct));
