    {
        double zr = cr;
        double zi = ci;
        for (int i = 0; i < 50; i++)
        {
            double tr = zr * zr;
            double ti = zi * zi;
            if (tr + ti > 4.0) return false;
            zi = 2.0 * zr * zi + ci;
            zr = tr - ti + cr;
        }
        return true;
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
