                Vector256<double> cmp1 = Avx.Compare(sum1, four, FloatComparisonMode.OrderedLessThanOrEqualNonSignaling);
                res1 = Avx.And(res1, cmp1);

                int mask0 = Avx.MoveMask(res0);
                int mask1 = Avx.MoveMask(res1);
                if ((mask0 | mask1) == 0)
                    break;

                Vector256<double> zrzi0 = Avx.Multiply(zr0, zi0);
                zi0 = Avx.Add(Avx.Add(zrzi0, zrzi0), ciV);
                zr0 = Avx.Add(Avx.Subtract(tr0, ti0), cr0);

                Vector256<double> zrzi1 = Avx.Multiply(zr1, zi1);
                zi1 = Avx.Add(Avx.Add(zrzi1, zrzi1), ciV);
                zr1 = Avx.Add(Avx.Subtract(tr1, ti1), cr1);
            }

            int m0 = Avx.MoveMask(res0);
            int m1 = Avx.MoveMask(res1);
            data[rowOffset + b] = (byte)((m0 << 4) | m1);
        }

        if (n % 8 != 0)
        {
            int byteVal = 0;
            int xBase = fullBytes * 8;
            for (int x = xBase; x < n; x++)
            {
                double cr = 2.0 * x / n - 1.5;
                if (CheckPixel(cr, ci))
                {
                    byteVal |= (1 << (7 - (x - xBase)));
                }
            }
            data[rowOffset + fullBytes] = (byte)byteVal;
        }
    }

    private static void ComputeRowScalar(int y, int n, int lineLen, byte[] data)
    {
        int rowOffset = y * lineLen;
        double ci = 2.0 * y / n - 1.0;
        int fullBytes = n / 8;

        for (int b = 0; b < fullBytes; b++)
        {
            int byteVal = 0;
            int xBase = b * 8;
            for (int p = 0; p < 8; p++)
            {
                double cr = 2.0 * (xBase + p) / n - 1.5;
                if (CheckPixel(cr, ci))
                {
                    byteVal |= (1 << (7 - p));
                }
            }
            data[rowOffset + b] = (byte)byteVal;
        }

        if (n % 8 != 0)
        {
            int byteVal = 0;
            int xBase = fullBytes * 8;
            for (int x = xBase; x < n; x++)
            {
                double cr = 2.0 * x / n - 1.5;
                if (CheckPixel(cr, ci))
                {
                    byteVal |= (1 << (7 - (x - xBase)));
                }
            }
            data[rowOffset + fullBytes] = (byte)byteVal;
        }
    }

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        int lineLen = (n + 7) / 8;
        byte[] data = new byte[n * lineLen];

        if (Avx.IsSupported)
        {
            int fullBytes = n / 8;
            CrBlock[] crBlocks = new CrBlock[fullBytes];
            for (int b = 0; b < fullBytes; b++)
            {
                int x = b * 8;
                crBlocks[b].Cr0 = Vector256.Create(
                    2.0 * (x + 3) / n - 1.5,
                    2.0 * (x + 2) / n - 1.5,
                    2.0 * (x + 1) / n - 1.5,
                    2.0 * (x + 0) / n - 1.5
                );
                crBlocks[b].Cr1 = Vector256.Create(
                    2.0 * (x + 7) / n - 1.5,
                    2.0 * (x + 6) / n - 1.5,
                    2.0 * (x + 5) / n - 1.5,
                    2.0 * (x + 4) / n - 1.5
                );
            }

            Vector256<double> four = Vector256.Create(4.0);
            Vector256<double> allOnes = Avx.Compare(four, four, FloatComparisonMode.OrderedLessThanOrEqualNonSignaling);

            Parallel.For(0, n, y =>
            {
                ComputeRowAvx(y, n, lineLen, data, crBlocks, four, allOnes);
            });
        }
        else
        {
            Parallel.For(0, n, y =>
            {
                ComputeRowScalar(y, n, lineLen, data);
            });
        }

        using Stream stdout = Console.OpenStandardOutput();
        byte[] header = Encoding.ASCII.GetBytes($"P4\n{n} {n}\n");
        stdout.Write(header, 0, header.Length);
        stdout.Write(data, 0, data.Length);
    }
