    private static double Energy(Body[] bodies)
    {
        double energy = 0.0;
        for (int i = 0; i < bodies.Length; i++)
        {
            ref readonly Body bi = ref bodies[i];
            energy += 0.5 * bi.Mass * (bi.Vx * bi.Vx + bi.Vy * bi.Vy + bi.Vz * bi.Vz);
            for (int j = i + 1; j < bodies.Length; j++)
            {
                ref readonly Body bj = ref bodies[j];
                double dx = bi.X - bj.X;
                double dy = bi.Y - bj.Y;
                double dz = bi.Z - bj.Z;
                double distance = Math.Sqrt(dx * dx + dy * dy + dz * dz);
                energy -= (bi.Mass * bj.Mass) / distance;
            }
        }
        return energy;
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void Advance(Body[] bodies, double dt, int n)
    {
        ref Body b0 = ref bodies[0];
        ref Body b1 = ref bodies[1];
        ref Body b2 = ref bodies[2];
        ref Body b3 = ref bodies[3];
        ref Body b4 = ref bodies[4];

        double m0 = b0.Mass, m1 = b1.Mass, m2 = b2.Mass, m3 = b3.Mass, m4 = b4.Mass;

        for (int step = 0; step < n; step++)
        {
            Interact(ref b0, ref b1, m1, m0, dt);
            Interact(ref b0, ref b2, m2, m0, dt);
            Interact(ref b0, ref b3, m3, m0, dt);
            Interact(ref b0, ref b4, m4, m0, dt);
            Interact(ref b1, ref b2, m2, m1, dt);
            Interact(ref b1, ref b3, m3, m1, dt);
            Interact(ref b1, ref b4, m4, m1, dt);
            Interact(ref b2, ref b3, m3, m2, dt);
            Interact(ref b2, ref b4, m4, m2, dt);
            Interact(ref b3, ref b4, m4, m3, dt);

            b0.X += dt * b0.Vx; b0.Y += dt * b0.Vy; b0.Z += dt * b0.Vz;
            b1.X += dt * b1.Vx; b1.Y += dt * b1.Vy; b1.Z += dt * b1.Vz;
            b2.X += dt * b2.Vx; b2.Y += dt * b2.Vy; b2.Z += dt * b2.Vz;
            b3.X += dt * b3.Vx; b3.Y += dt * b3.Vy; b3.Z += dt * b3.Vz;
            b4.X += dt * b4.Vx; b4.Y += dt * b4.Vy; b4.Z += dt * b4.Vz;
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Interact(ref Body bi, ref Body bj, double mj, double mi, double dt)
    {
        double dx = bi.X - bj.X;
        double dy = bi.Y - bj.Y;
        double dz = bi.Z - bj.Z;
        double d2 = dx * dx + dy * dy + dz * dz;
        double mag = dt / (d2 * Math.Sqrt(d2));

        bi.Vx -= dx * mj * mag;
        bi.Vy -= dy * mj * mag;
        bi.Vz -= dz * mj * mag;

        bj.Vx += dx * mi * mag;
        bj.Vy += dy * mi * mag;
        bj.Vz += dz * mi * mag;
    }
