        c['R'] = (byte)'Y'; c['r'] = (byte)'Y';
        c['W'] = (byte)'W'; c['w'] = (byte)'W';
        c['S'] = (byte)'S'; c['s'] = (byte)'S';
        c['Y'] = (byte)'R'; c['y'] = (byte)'R';
        c['K'] = (byte)'M'; c['k'] = (byte)'M';
        c['V'] = (byte)'B'; c['v'] = (byte)'B';
        c['H'] = (byte)'D'; c['h'] = (byte)'D';
        c['D'] = (byte)'H'; c['d'] = (byte)'H';
        c['B'] = (byte)'V'; c['b'] = (byte)'V';
        c['N'] = (byte)'N'; c['n'] = (byte)'N';

        return c;
    }

    static void Main(string[] args)
    {
        int n = args.Length > 0 ? int.Parse(args[0]) : 0;

        Stream stdin = Console.OpenStandardInput();
        Stream stdout = Console.OpenStandardOutput();

        byte[] inBuf = new byte[256 * 1024];
        byte[] outBuf = new byte[512 * 1024];

        byte[] seqBuf = new byte[1024 * 1024];
        int seqLen = 0;

        byte[] headerBuf = new byte[4096];
        int headerLen = 0;

        bool inHeader = false;
        bool hasSequence = false;

        int bytesRead;
        while ((bytesRead = stdin.Read(inBuf, 0, inBuf.Length)) > 0)
        {
            int i = 0;
            while (i < bytesRead)
            {
                if (inHeader)
                {
                    int nlPos = Array.IndexOf(inBuf, (byte)'\n', i, bytesRead - i);
                    if (nlPos == -1)
                    {
                        AppendHeader(ref headerBuf, ref headerLen, inBuf, i, bytesRead - i);
                        i = bytesRead;
                    }
                    else
                    {
                        AppendHeader(ref headerBuf, ref headerLen, inBuf, i, nlPos - i + 1);
                        i = nlPos + 1;
                        inHeader = false;
                    }
                }
                else
                {
                    int nextHeader = Array.IndexOf(inBuf, (byte)'>', i, bytesRead - i);
                    if (nextHeader == -1)
                    {
                        if (hasSequence)
                        {
                            AppendSeq(ref seqBuf, ref seqLen, inBuf, i, bytesRead - i);
                        }
                        i = bytesRead;
                    }
                    else
                    {
                        if (hasSequence)
                        {
                            AppendSeq(ref seqBuf, ref seqLen, inBuf, i, nextHeader - i);
                            FlushSequence(stdout, outBuf, headerBuf, headerLen, seqBuf, seqLen);
                            headerLen = 0;
                            seqLen = 0;
                        }
                        hasSequence = true;
                        inHeader = true;
                        i = nextHeader;
                    }
                }
            }
        }

        if (hasSequence)
        {
            FlushSequence(stdout, outBuf, headerBuf, headerLen, seqBuf, seqLen);
        }

        stdout.Flush();
    }

    static void AppendHeader(ref byte[] headerBuf, ref int headerLen, byte[] inBuf, int start, int count)
    {
        if (headerLen + count > headerBuf.Length)
        {
            long newCapLong = Math.Max((long)headerBuf.Length * 2, (long)headerLen + count);
            Array.Resize(ref headerBuf, (int)newCapLong);
        }
        Buffer.BlockCopy(inBuf, start, headerBuf, headerLen, count);
        headerLen += count;
    }

    static void AppendSeq(ref byte[] seqBuf, ref int seqLen, byte[] inBuf, int start, int count)
    {
        if (seqLen + count > seqBuf.Length)
        {
            long newCapLong = Math.Max((long)seqBuf.Length * 2, (long)seqLen + count);
            if (newCapLong > 0x7FFFFFC7) newCapLong = 0x7FFFFFC7;
            Array.Resize(ref seqBuf, (int)newCapLong);
        }
        int end = start + count;
        for (int k = start; k < end; k++)
        {
            byte b = inBuf[k];
            if (b > (byte)' ')
            {
                seqBuf[seqLen++] = b;
            }
        }
    }

    static void FlushSequence(Stream stdout, byte[] outBuf, byte[] headerBuf, int headerLen, byte[] seqBuf, int seqLen)
    {
        if (headerLen > 0)
        {
            stdout.Write(headerBuf, 0, headerLen);
            if (headerBuf[headerLen - 1] != '\n')
            {
                stdout.WriteByte((byte)'\n');
            }
        }

        if (seqLen == 0) return;

        int outPos = 0;
        int p = seqLen - 1;

        while (p >= 59)
        {
            for (int k = 0; k < 60; k++)
            {
                outBuf[outPos++] = comp[seqBuf[p--]];
            }
            outBuf[outPos++] = (byte)'\n';

            if (outPos >= outBuf.Length - 64)
            {
                stdout.Write(outBuf, 0, outPos);
                outPos = 0;
            }
        }

        if (p >= 0)
        {
            int rem = p + 1;
            for (int k = 0; k < rem; k++)
            {
                outBuf[outPos++] = comp[seqBuf[p--]];
            }
            outBuf[outPos++] = (byte)'\n';
        }

        if (outPos > 0)
        {
            stdout.Write(outBuf, 0, outPos);
        }
    }
